CREATE TABLE public.library_items (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  category text,
  names text NOT NULL,
  cas_number text,
  molecular_weight text,
  molecular_size text,
  size_basis text,
  chemical_formula text,
  sequence text,
  salt_form text,
  termini_modifications text,
  notes text,
  confidence text,
  ambiguity_notes text,
  source_url text,
  created_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

GRANT SELECT, INSERT, UPDATE, DELETE ON public.library_items TO authenticated;
GRANT ALL ON public.library_items TO service_role;

ALTER TABLE public.library_items ENABLE ROW LEVEL SECURITY;

CREATE POLICY "library_items select for authenticated"
  ON public.library_items FOR SELECT TO authenticated USING (true);

CREATE POLICY "library_items insert admin"
  ON public.library_items FOR INSERT TO authenticated
  WITH CHECK (public.has_role(auth.uid(), 'admin'));

CREATE POLICY "library_items update admin"
  ON public.library_items FOR UPDATE TO authenticated
  USING (public.has_role(auth.uid(), 'admin'))
  WITH CHECK (public.has_role(auth.uid(), 'admin'));

CREATE POLICY "library_items delete admin"
  ON public.library_items FOR DELETE TO authenticated
  USING (public.has_role(auth.uid(), 'admin'));

CREATE TRIGGER trg_library_items_updated_at
  BEFORE UPDATE ON public.library_items
  FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

CREATE UNIQUE INDEX library_items_cas_unique
  ON public.library_items (lower(cas_number)) WHERE cas_number IS NOT NULL;
CREATE UNIQUE INDEX library_items_names_unique
  ON public.library_items (lower(names)) WHERE names IS NOT NULL;

